#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using PII = pair<int, int>;

char A[15][15], B[15][15];
const int di[4] = {-1, 1, 0, 0};
const int dj[4] = {0, 0, -1, 1};
int layerIdx[65][15][15];
int timeDist[15][15];
int nextId = 1;

struct Edge {
    int u, v;
    ll cap, flow;
    Edge(int u_, int v_, ll c) : u(u_), v(v_), cap(c), flow(0) {}
};

struct Dinic {
    int n;
    vector<Edge> edges;
    vector<vector<int>> adj;
    vector<int> depth, start;

    Dinic(int N) : n(N), edges(), adj(N), depth(N), start(N) {}

    void link(int u, int v, ll c) {
        if (u == v) return;
        edges.emplace_back(u, v, c);
        adj[u].push_back(edges.size() - 1);
        edges.emplace_back(v, u, 0);
        adj[v].push_back(edges.size() - 1);
    }

    bool levelGraph(int s, int t) {
        fill(depth.begin(), depth.end(), n + 1);
        queue<int> q;
        q.push(s);
        depth[s] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (u == t) break;
            for (int idx : adj[u]) {
                Edge &e = edges[idx];
                if (e.flow < e.cap && depth[e.v] > depth[e.u] + 1) {
                    depth[e.v] = depth[e.u] + 1;
                    q.push(e.v);
                }
            }
        }
        return depth[t] <= n;
    }

    ll augment(int u, int t, ll bottleneck) {
        if (u == t || bottleneck == 0) return bottleneck;
        for (int &i = start[u]; i < (int)adj[u].size(); ++i) {
            Edge &e = edges[adj[u][i]];
            if (depth[e.v] == depth[e.u] + 1) {
                ll available = e.cap - e.flow;
                if (bottleneck != -1 && available > bottleneck) available = bottleneck;
                ll pushed = augment(e.v, t, available);
                if (pushed > 0) {
                    e.flow += pushed;
                    edges[adj[u][i] ^ 1].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll flow(int s, int t) {
        ll total = 0;
        while (levelGraph(s, t)) {
            fill(start.begin(), start.end(), 0);
            ll pushed;
            while ((pushed = augment(s, t, -1)) > 0) {
                total += pushed;
            }
        }
        return total;
    }
};

int main() {
    memset(timeDist, -1, sizeof(timeDist));
    int N, T;
    cin >> N >> T;
    for (int i = 1; i <= N; ++i) {
        cin >> (A[i] + 1);
    }
    for (int t = 0; t <= T + 1; ++t) {
        for (int r = 1; r <= N; ++r) {
            for (int c = 1; c <= N; ++c) {
                layerIdx[t][r][c] = nextId++;
            }
        }
    }
    nextId++;
    for (int i = 1; i <= N; ++i) {
        cin >> (B[i] + 1);
    }
    queue<PII> q;
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (A[i][j] == 'Z') {
                q.emplace(i, j);
                timeDist[i][j] = 0;
            }
        }
    }
    while (!q.empty()) {
        auto [y, x] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int ny = y + di[d], nx = x + dj[d];
            if (ny >= 1 && ny <= N && nx >= 1 && nx <= N && A[ny][nx] != 'Y' && timeDist[ny][nx] == -1) {
                timeDist[ny][nx] = timeDist[y][x] + 1;
                q.emplace(ny, nx);
            }
        }
    }
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (timeDist[i][j] == -1) timeDist[i][j] = 1e9;
            if (timeDist[i][j] > T) timeDist[i][j] = 1e9;
        }
    }
    int source = 0, sink = nextId - 1;
    Dinic network(nextId);
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (A[i][j] >= '1' && A[i][j] <= '9') {
                network.link(source, layerIdx[0][i][j], A[i][j] - '0');
            }
        }
    }
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (A[i][j] == 'Y' || A[i][j] == 'Z') continue;
            for (int d = 0; d < 4; ++d) {
                int ny = i + di[d], nj = j + dj[d];
                if (ny >= 1 && ny <= N && nj >= 1 && nj <= N && A[ny][nj] != 'Y' && A[ny][nj] != 'Z') {
                    for (int step = 0; step < T; ++step) {
                        if (timeDist[ny][nj] >= step + 1 && timeDist[i][j] > step) {
                            network.link(layerIdx[step][i][j], layerIdx[step + 1][ny][nj], 1000);
                        }
                    }
                }
            }
        }
    }
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (A[i][j] == 'Y' || A[i][j] == 'Z') continue;
            for (int step = 0; step <= T; ++step) {
                if (B[i][j] >= '1' && B[i][j] <= '9') {
                    network.link(layerIdx[step][i][j], layerIdx[T + 1][i][j], B[i][j] - '0');
                }
            }
        }
    }
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (A[i][j] == 'Y' || A[i][j] == 'Z') continue;
            if (B[i][j] >= '1' && B[i][j] <= '9') {
                network.link(layerIdx[T + 1][i][j], sink, B[i][j] - '0');
            }
        }
    }
    cout << (int)network.flow(source, sink) << '\n';
    return 0;
}
